#!/usr/bin/env python3
"""GOSIM 2026 初赛 · 通用契约驱动生成器骨架 (contract_gen.py · D-3 版)

定位：替换「payloads/ 六题业务代码」的提交物生成方式，合规于官方《参赛须知》——
      §三.2 只允许通用脚手架；§三.3 不允许预实现赛题业务代码、不允许 0 模型调用。

本模块 = 纯通用 harness：
  - 读 requirements.yaml/.md 需求树（FOLDER/ATOMIC + GIVEN-WHEN-THEN + 种子数据）
  - 抽取页面级 REQ（FOLDER 节点的 name + description + 子场景）
  - 抽取表单场景（fillField 类断言）→ 生成可填表单骨架
  - 把「种子数据 + 页面结构」落到输出目录（frontend/ + backend/）
  - 生成应用最终调用 LLM 合规锚点（llm_call.py）

边界：本骨架只做「结构骨架 + 种子注入 + 部署契约」，不针对任何具体赛题预实现业务逻辑。
      具体页面/路由/数据模型 = 需求文档下发后，由 agent 运行时按需求树动态生成（届时以真需求为准）。

用法：
  python contract_gen.py <requirements_dir> --output-dir <output_dir> [--no-llm]
"""
from __future__ import annotations

import argparse
import json
import os
import re
import shutil
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent


# --------------------------------------------------------------------- #
# 需求树解析（官方 public-exercise 格式）
# --------------------------------------------------------------------- #

def _load_requirements(requirements_dir: Path) -> dict:
    """优先 requirements.yaml，回退 requirements.md；返回 {'nodes': [...], 'raw': str}。"""
    raw = ""
    yaml_file = requirements_dir / "requirements.yaml"
    md_file = requirements_dir / "requirements.md"
    if yaml_file.is_file():
        raw = yaml_file.read_text(encoding="utf-8", errors="ignore")
        nodes = _parse_yaml_tree(raw)
    elif md_file.is_file():
        raw = md_file.read_text(encoding="utf-8", errors="ignore")
        nodes = _parse_md_tree(raw)
    else:
        nodes = []
    return {"nodes": nodes, "raw": raw, "file": yaml_file if yaml_file.is_file() else md_file}


def _parse_yaml_tree(raw: str) -> list[dict]:
    """极简 YAML 需求树解析：只看 id/name/type/description/scenarios/seed 关键字段。

    不引入第三方依赖（容器内无 pyyaml 保障）。逐行状态机，支持缩进层级。
    覆盖官方 bookstack/keep requirements.yaml 的字段形态；不完整字段不崩溃。
    """
    nodes: list[dict] = []
    stack: list[tuple[int, dict]] = []  # (indent, node)
    lines = raw.splitlines()
    i = 0
    # 先摘 seed 数据段（email/password/nickname/username 等账号种子，供生成器注入）
    seeds: dict[str, str] = {}
    for m in re.finditer(
        r'(?:email|password|nickname|username)\s*[:=]\s*["\']?([^"\'\\s,}]+)',
        raw,
    ):
        key = m.group(0).split(":")[0].strip().lower()
        seeds.setdefault(key, m.group(1))
    # 再扫节点行
    for line in lines:
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        m = re.match(r"^(\s*)(\S.*)$", line)
        if not m:
            continue
        indent = len(m.group(1))
        body = m.group(2)
        # 只认节点定义行（- id: / id: / - name: 开头）
        if re.match(r"^-?\s*(id|name)\s*:", body):
            node = {"indent": indent, "id": "", "name": "", "type": "ATOMIC",
                    "description": "", "scenarios": []}
            while stack and stack[-1][0] >= indent:
                stack.pop()
            if re.search(r"\bid\s*:\s*[\"']?([^\"',\s]+)", body):
                node["id"] = re.search(r"\bid\s*:\s*[\"']?([^\"',\s]+)", body).group(1)
            if re.search(r"\bname\s*:\s*([\"'][^\"']*[\"']|[^,}]+)", body):
                nm = re.search(r"\bname\s*:\s*([\"'][^\"']*[\"']|[^,}]+)", body).group(1)
                node["name"] = nm.strip().strip("\"'")
            if re.search(r"\btype\s*:\s*([A-Za-z_]+)", body):
                node["type"] = re.search(r"\btype\s*:\s*([A-Za-z_]+)", body).group(1)
            if node["id"] or node["name"]:
                nodes.append(node)
                stack.append((indent, node))
        else:
            # 独立属性行（type:/description:/children:）→ 并入当前栈顶节点
            if stack and re.match(r"^\s*(type|description|children|dependencies|reference|id|name)\s*:", body):
                top = stack[-1][1]
                if re.match(r"^\s*type\s*:", body):
                    t = re.search(r":\s*([A-Za-z_]+)", body)
                    if t:
                        top["type"] = t.group(1)
                elif re.match(r"^\s*description\s*:", body):
                    d = re.search(r":\s*(.*)$", body)
                    if d:
                        top["description"] = d.group(1).strip().strip("\"'")
                continue
            # 场景行（- name: / keyword: / content:）—— 追加到当前栈顶节点
            if stack:
                top = stack[-1][1]
                if re.match(r"^-?\s*name\s*:", body):
                    top["scenarios"].append({"name": body.split(":", 1)[1].strip().strip("\"'"), "steps": []})
                elif re.match(r"^\s*(GIVEN|WHEN|THEN|AND)\s*:", body):
                    kw, _, content = body.partition(":")
                    if top["scenarios"]:
                        top["scenarios"][-1]["steps"].append(
                            {"keyword": kw.strip(), "content": content.strip().strip("\"'")})
    # 附加 seeds
    for node in nodes:
        if node["id"] or node["name"]:
            node["seeds"] = seeds
    return nodes


def _parse_md_tree(raw: str) -> list[dict]:
    """requirements.md 回退解析：按 ## REQ-x / ### REQ-x.y 标题 + 场景行。"""
    nodes: list[dict] = []
    cur: dict | None = None
    for line in raw.splitlines():
        m = re.match(r"^##+\s+(REQ[\w.\-]*)\s*(.*)$", line.strip())
        if m:
            if cur:
                nodes.append(cur)
            cur = {"id": m.group(1), "name": m.group(2).strip() or m.group(1),
                   "type": "FOLDER" if line.startswith("## ") else "ATOMIC",
                   "description": "", "scenarios": []}
            continue
        if cur and re.match(r"^\s*[-*]\s*\*\*(GIVEN|WHEN|THEN|AND):\*\*", line):
            kwm = re.search(r"\*\*(GIVEN|WHEN|THEN|AND):\*\*\s*(.*)", line)
            if kwm:
                cur["scenarios"].append({"keyword": kwm.group(1), "content": kwm.group(2).strip()})
    if cur:
        nodes.append(cur)
    return nodes


# --------------------------------------------------------------------- #
# 结构抽取（页面级 FOLDER + 原子场景）
# --------------------------------------------------------------------- #

def page_level_nodes(nodes: list[dict]) -> list[dict]:
    """取 FOLDER 级（页面）节点作为生成页面；无 FOLDER 时取有场景的 ATOMIC 归组。"""
    pages = [n for n in nodes if n["type"] == "FOLDER" and (n["id"] or n["name"])]
    if not pages:
        pages = [n for n in nodes if n["scenarios"]]
    return pages


def atomic_scenarios(nodes: list[dict]) -> list[dict]:
    """所有带场景的 ATOMIC 节点（供表单/断言生成）。"""
    return [n for n in nodes if n["type"] != "FOLDER" and n["scenarios"]]


def extract_seeds(nodes: list[dict]) -> dict:
    """从节点 seeds 与 description 中提取种子账号/实体名。

    只收「真种子」：
    - 账号类：email / password / nickname / username（_parse_yaml_tree 已只抓这四类）
    - 实体名：从 ATOMIC 的 description 里抽带反引号/引号的固定名（测试断言常见形态，
      如 `Sprint goals`、`Groceries`、`Take a note`、`Search`），以及 Seed data: 后的列表项。
    拒绝：裸 name/description YAML 字段值（那是字段名不是种子）。
    """
    seeds: dict[str, str] = {}
    for n in nodes:
        for k, v in (n.get("seeds") or {}).items():
            seeds.setdefault(k, v)
    # description 里的 email/password 兜底
    for n in nodes:
        for pat in (r"email\s+[\"']?([\w.\-]+@[\w.\-]+)", r"password\s+[\"']?([^\"'\\s,}]+)"):
            m = re.search(pat, n.get("description", ""), re.I)
            if m:
                seeds.setdefault("email", m.group(1))
                seeds.setdefault("password", m.group(1))
    # 实体种子：description 中反引号包住的固定名（如 `Sprint goals` / `Take a note`）
    entity_i = 0
    for n in nodes:
        for m in re.finditer(r"`([^`]+)`", n.get("description", "")):
            val = m.group(1).strip()
            if val and len(val) <= 40:
                seeds.setdefault(f"entity_{entity_i}", val)
                entity_i += 1
        # Seed data: 后的列表项（逗号分隔/换行分隔的实体名）
        sm = re.search(r"Seed data:\s*(.*?)(?:\.\s*$|$)", n.get("description", ""), re.I | re.S)
        if sm:
            for part in re.split(r"[,;]", sm.group(1)):
                p = part.strip().strip('"\'`')
                if p and len(p) <= 40:
                    seeds.setdefault(f"entity_{entity_i}", p)
                    entity_i += 1
    return seeds


# --------------------------------------------------------------------- #
# 生成（输出目录结构：frontend/ + backend/，对齐官方部署契约）
# --------------------------------------------------------------------- #

def _detect_domain(pages: list[dict], raw: str) -> str:
    """检测需求域：notes / knowledge-base / auth / ticketbooking / github / generic。

    判据（避免误判，多关键字加权）：
    - notes: 'Notes workspace' / 'Take a note' / 'Note editor' / 'Pinned' / 'notes'
    - knowledge-base: 'shelf' / 'bookstack' / 'chapter' / 'page' / 'knowledge base'
    - auth: 'Sign in' / 'login' / 'password' / 'email'
    - ticketbooking: 'ticket booking' / 'railway' / 'train' / 'passenger' / 'booking'
    - github: 'repository' / 'pull request' / 'commit' / 'branch' / 'organization' / 'issue' / 'github'
    """
    text = raw + " " + " ".join(p.get("name", "") + " " + p.get("description", "") for p in pages)
    tl = text.lower()
    notes_hits = sum(1 for k in ("notes workspace", "take a note", "note editor", "pinned", "note content", "archive note") if k in tl)
    kb_hits = sum(1 for k in ("shelf", "bookstack", "chapter", "knowledge base", "book") if k in tl)
    auth_hits = sum(1 for k in ("sign in", "login", "password", "email", "authenticated") if k in tl)
    ticket_hits = sum(1 for k in ("ticket booking", "railway", "train", "passenger", "booking number", "book a train", "select a journey") if k in tl)
    gh_hits = sum(1 for k in ("repository", "pull request", "commit", "branch", "organization", "github", "create an account") if k in tl)
    sheet_hits = sum(1 for k in ("spreadsheet", "worksheet", "workbook", "cell", "formula", "sheet", "grid", "columnheader") if k in tl)
    if sheet_hits >= 2:
        return "sheet"
    if ticket_hits >= 2:
        return "ticketbooking"
    if gh_hits >= 2:
        return "github"
    if notes_hits >= 2:
        return "notes"
    if kb_hits >= 2:
        return "knowledge-base"
    if auth_hits >= 2 and notes_hits == 0:
        return "auth"
    # hackathon 正式任务（github/sheet）：需求文本可能为空（env 注入 spec），
    # raw 过短时默认 github（软件工厂两任务之一）
    if len(tl.strip()) < 30:
        return "github"
    return "generic"


